module popcount32 (
    input wire clk,
    input wire rst_n,
    input wire valid_i,
    input wire [31:0] a_i,
    input wire [31:0] b_i,
    output reg valid_o,
    output reg [5:0] y_o
);

// Population count using tree of adders
// Efficiently structured to minimize depth while keeping area reasonable
wire [5:0] total_0;

// Stage 1: Count bits in groups of 2
wire [1:0] s1[15:0];
assign s1[0] = a_i[0:0] + a_i[1:1];
assign s1[1] = a_i[2:2] + a_i[3:3];
